import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));

if (mode === 'latin') {
  const words = [
    ['Crème Brûlée', 'creme-brulee'], ['Łódź', 'lodz'],
    ['ÀÁÂÃÄÅ ĆČÇ ÈÉÊË ÌÍÎÏ Ñ ÒÓÔÕÖ ÙÚÛÜ ÝŸ', 'aaaaaa-ccc-eeee-iiii-n-ooooo-uuuu-yy'],
    ['Dvořák São Tomé Zürich', 'dvorak-sao-tome-zurich'],
    ['Việt Nam', 'viet-nam'], ['İstanbul', 'istanbul'],
    ['Smørrebrød Æsir Œuvre Straße', 'smorrebrod-aesir-oeuvre-strasse'],
    ['Øresund Đakovo ŁÓDŹ', 'oresund-dakovo-lodz'],
    ['Ð Þ Ħ ı Ŧ ſ', 'd-th-h-i-t-s'],
    ['ﬀ ﬁ ﬂ ﬃ ﬄ ﬅ ﬆ', 'ff-fi-fl-ffi-ffl-st-st'],
    ['ẞ Æ Œ Ø Đ Ł Ħ Ð Þ Ŧ', 'ss-ae-oe-o-d-l-h-d-th-t'],
  ];
  for (const [input, expected] of words) {
    check(input, expected);
    check(input.normalize('NFD'), expected);
    check(input.toLowerCase(), expected);
  }
  // Exhaust all canonically decomposable Latin letters whose base is ASCII.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const plain = letter.toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
    if (!/^[a-z]+$/.test(plain)) continue;
    check(letter, plain);
    check(letter.normalize('NFD'), plain);
    check('x' + letter + 'y', 'x' + plain + 'y');
  }
  check('Cafe\u0301 au lait', 'cafe-au-lait');
  check('a\u0301\u0323b e\u0308\u0301lan', 'ab-elan');
  check(' --Ærø / Straße & Crème 42!! ', 'aero-strasse-creme-42');
  check('Crème Москва Αθήνα 東京', 'creme-москва-αθήνα-東京');
} else if (mode === 'preserve') {
  const cases = [
    ['', ''], [' --- ! 🌍 ', ''], ['Hello, World!', 'hello-world'],
    ['  --Release 2.0--  ', 'release-2-0'], ['a___b\tc\nd', 'a-b-c-d'],
    ['foo---bar', 'foo-bar'], ['123 ٤٥٦ １２３', '123-٤٥٦-１２３'],
    ['Привет мир', 'привет-мир'], ['Ёж Йога', 'ёж-йога'],
    ['Αθήνα κόσμος', 'αθήνα-κόσμος'], ['東京 日本語', '東京-日本語'],
    ['한글 가각', '한글-가각'], ['العربية עברית', 'العربية-עברית'],
    ['नमस्ते', 'नमस-त'], ['α\u0301β', 'α-β'],
  ];
  for (const [input, expected] of cases) check(input, expected);
  // Every individual non-Latin letter and number must retain the old behavior,
  // including precomposed accents and compatibility characters in other scripts.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const ch = String.fromCodePoint(cp);
    if (!/^[\p{L}\p{N}]$/u.test(ch) || /^\p{Script=Latin}$/u.test(ch)) continue;
    const expected = ch.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
    check(ch, expected);
  }
} else {
  throw new Error('Unknown check mode');
}
console.log('OK: ' + mode);
